def compute(vars):
    unrecognized_tax_benefits = vars["v1"]
    earnings_impact_benefits = vars["v2"]

    if unrecognized_tax_benefits == 0:
        return None

    ratio = earnings_impact_benefits / unrecognized_tax_benefits
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "unrecognized_tax_benefits": unrecognized_tax_benefits,
            "earnings_impact_benefits": earnings_impact_benefits,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
